Commit:     Ben Campbell <benc@thunderbird.net>
CommitDate: Thu Sep 18 11:28:40 2025 +0100

    Bug 1986399 - Increase autosync download group size from 50KB to 2MB. r=mkmelin


    50KB Limit seemed a little archaic. Even the smallest of modern emails are
    so bloated that they'll be pushing 30KB, so the autosync would only ever
    download one or two messages at a time.

    Also removes the unused (and thus misleading) nsIAutoSyncManager.groupSize
    attr from the public interface.

    Differential Revision: https://phabricator.services.mozilla.com/D265046

diff --git a/mailnews/imap/public/nsIAutoSyncManager.idl b/mailnews/imap/public/nsIAutoSyncManager.idl
index 76ea2f694e6..01771451921 100644
--- a/mailnews/imap/public/nsIAutoSyncManager.idl
+++ b/mailnews/imap/public/nsIAutoSyncManager.idl
@@ -89,13 +89,6 @@ interface nsIAutoSyncManager : nsISupports {
   const long dmParallel = 0;
   const long dmChained = 1;

-  /**
-   * Suggested minimum grouping size in bytes for message downloads.
-   * Setting this attribute to 0 resets its value to the
-   * hardcoded default.
-   */
-  attribute unsigned long groupSize;
-
   /**
    * Active strategy function to prioritize
    * messages in the download queue
diff --git a/mailnews/imap/src/nsAutoSyncManager.cpp b/mailnews/imap/src/nsAutoSyncManager.cpp
index f5591f3b052..5b03d1a8c75 100644
--- a/mailnews/imap/src/nsAutoSyncManager.cpp
+++ b/mailnews/imap/src/nsAutoSyncManager.cpp
@@ -50,7 +50,7 @@ static nsresult IsSibling(nsIAutoSyncState* syncA, nsIAutoSyncState* syncB,
 }

 // recommended size of each group of messages per download
-static const uint32_t kDefaultGroupSize = 50U * 1024U /* 50K */;
+static const uint32_t kDefaultGroupSize = 2000U * 1024U /* 2MB */;

 nsDefaultAutoSyncMsgStrategy::nsDefaultAutoSyncMsgStrategy() = default;

@@ -1105,16 +1105,6 @@ nsresult nsAutoSyncManager::HandleDownloadErrorFor(
   return NS_OK;
 }

-NS_IMETHODIMP nsAutoSyncManager::GetGroupSize(uint32_t* aGroupSize) {
-  NS_ENSURE_ARG_POINTER(aGroupSize);
-  *aGroupSize = mGroupSize;
-  return NS_OK;
-}
-NS_IMETHODIMP nsAutoSyncManager::SetGroupSize(uint32_t aGroupSize) {
-  mGroupSize = aGroupSize ? aGroupSize : kDefaultGroupSize;
-  return NS_OK;
-}
